      {
        "name": "sindy",
        "version": "1.3.0",
        "deterministic": true
      },
      {
        "name": "pareto-refine",
        "version": "0.4.1",
        "deterministic": true
      }
    ]
  },
  "tags": [
    "ecology",
    "predator-prey",
    "benchmark"
  ]
}
